/* Éttermek: az azonosítók előzetes meetingválogatást jelölnek, nem teljes piacot. */
(()=>{'use strict';const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const lk=(u,t='Forrás')=>/^https?:\/\//.test(u||'')?`<a href="${esc(u)}" target="_blank" rel="noopener">${esc(t)} ↗</a>`:'nem igazolt';const fmt=n=>typeof n==='number'?new Intl.NumberFormat('hu-HU').format(n)+' Ft':'ár nem igazolt';let ids=[['E09','Chill','Közvetlenül az Óváros téren','Chill Bistro'],['E02','Oliva','Történelmi belváros','Oliva'],['E03','Fricska','Városi összehasonlítás','Fricska'],['E06','Gusto 13','Városi bistróreferencia','Gusto 13'],['E20','Skorpió','Belvárosi ebédmenü-összehasonlítás','']];const reviewNames={'E09':['Chill','Chill Bistro'],'E02':['Oliva'],'E03':['Fricska'],'E06':['Gusto 13'],'E20':['Skorpió']};const huTheme={'Food variety + polite service + ambience':'Kínálat, udvarias kiszolgálás, hangulat','Seasonal / idény menu satisfaction':'Szezonális menü','Portion / food quality':'Ételminőség és adag','Vintage / cozy interior + service':'Belső tér és kiszolgálás','Drink volume / billing dispute (limonádé)':'Italadag és számlázás','Service speed / wait time':'Kiszolgálás sebessége és várakozás','Professional service + booking needed (busy square)':'Kiszolgálás és asztalfoglalás','Value for money + cosy interior':'Ár-érték arány és belső tér','Atmosphere + friendly staff + food':'Hangulat, személyzet és étel','Portions / vegan options / fast kind service':'Adag, vegán választék és kiszolgálás','Location / terrace / garden':'Elhelyezkedés és terasz','Food + interior + service':'Étel, belső tér és kiszolgálás','Specific dish + desserts':'Fogások és desszertek','Hospitality / wine service':'Vendéglátás és bor','Family lunch / vegetarian-friendly':'Családi ebéd és vegetáriánus választék','Fast polite service + plating':'Kiszolgálás és tálalás','Creative plating / feeling like a guest':'Tálalás és vendégélmény','Setting / Séd / castle view; worth higher prices':'Környezet és ár-érték arány','Food above average; wait when full; friendly staff':'Étel, várakozás és személyzet','Food / service / atmosphere scores 5':'Étel, kiszolgálás és hangulat','Parking difficulty':'Parkolás','Delivery':'Kiszállítás'};function reputation(d,id){let names=reviewNames[id]||[];let matches=r=>names.some(n=>String(r[0]||'').trim()===n);let ratings=(d['Ratings 2026-11-09']||[]).slice(1).filter(matches);let themes=(d['Review themes']||[]).slice(1).filter(matches);let polarity=x=>/praised/i.test(x)?'Pozitív':/criticized/i.test(x)?'Kritika':/mixed/i.test(x)?'Vegyes':'Egyéb megfigyelés';return `<details><summary>Értékelések és vendégvélemények (${ratings.length} értékelésadat · ${themes.length} feljegyzett téma)</summary><p class="muted">Különböző időpontokból származó példák, nem reprezentatív minta. A pontszámok külön platformokhoz és esetenként közvetítő oldalakhoz tartoznak; nem vonjuk őket össze.</p><h4>Értékelések a forrásban</h4>${ratings.map(r=>`<p><b>${esc(r[1]||'Forrás nem ismert')}:</b> ${esc(r[2]||'nem ismert')} · véleményszám: ${esc(r[3]||'nem ismert')}<br><small>${esc(r[4]||'Az eredeti adat dátuma nem ismert')} · ellenőrzés: ${esc(r[6]||'nem ismert')} · ${lk(r[5])}</small></p>`).join('')||'<p>Nincs egyértelműen hozzárendelt értékelés.</p>'}<h4>Feljegyzett véleménytémák</h4>${themes.map(r=>`<p><b>${esc(polarity(String(r[2]||'')))} · ${esc(huTheme[r[1]]||r[1]||'Téma nem ismert')}</b>${r[5]?`<br><span>Kutatási összefoglaló: ${esc(r[5])}</span>`:''}${r[8]?`<br><span>Megjegyzés: ${esc(r[8])}</span>`:''}<br><small>A feljegyzett tapasztalat ideje: ${esc(r[3]||'nem ismert')} · forrás: ${esc(r[4]||'nem ismert')} · ellenőrzés: ${esc(r[7]||'nem ismert')} · ${lk(r[6])}</small></p>`).join('')||'<p>Ehhez az étteremhez nincs egyértelműen hozzárendelt véleménytéma a mentett adatokban.</p>'}</details>`} function view(d){let restaurants=d['Éttermek']||[], flow=(d['Dashboard adatfolyam']||[]).slice(1),dist=(d['Distance']||[]).slice(1),deliver=(d['Delivery and hours']||[]).slice(1),lunch=(d['Napi menü árak']||[]).slice(1);let cards=ids.map(([id,match,reason,distKey])=>{let r=restaurants.find(x=>x[0]===id);if(!r)return `<article class="comp-card"><h3>${esc(match)}</h3><p>Az éttermi törzsben nem található; ellenőrzés szükséges.</p></article>`;let ds=distKey?dist.find(x=>String(x[0]||'').startsWith(distKey)):null;let chan=deliver.filter(x=>x[0]==='Delivery presence'&&String(x[1]||'').toLowerCase().includes(match.toLowerCase())&&/^(Wolt|Foodora)$/.test(String(x[2])));let men=lunch.filter(x=>x[1]===id&&x[5]===2&&typeof x[7]==='number'&&x[6]!=='Elvitel');let dishes=flow.filter(x=>x[1]===id&&x[28]==='Önálló fogás'&&x[37]==='Helyszíni'&&typeof x[7]==='number'&&!/pizza|pinsa|felár|köret|savanyúság/i.test(String(x[4])));let examples=[];let seen=new Set();for(let x of dishes){let key=x[25]||x[0];if(seen.has(key))continue;seen.add(key);examples.push(x);if(examples.length>=3)break}return `<article class="comp-card"><span class="pill">${esc(reason)} · előzetes besorolás</span><h3>${esc(r[1])}</h3><p><b>Cím:</b> ${esc(r[3]||'nem igazolt')}</p><p><b>Kínálat:</b> ${esc(r[5]||'nem igazolt')}</p><p><b>Megközelítés:</b> ${ds?`${esc(ds[2])} becsült gyalogos útvonal; légvonalban ${esc(ds[1])}.${id==='E09'?' A térképi útvonal az Óváros téren kerülőt mutathat.':''}`:'Nincs rögzített gyalogos útvonal.'}</p><p><b>Ebédmenü:</b> ${men.length?men.map(x=>`${esc(x[4])}: ${fmt(x[7])} (${esc(x[13]||'?')} – ${esc(x[14]||'?')}; ${esc(x[6]||'csatorna nem egyértelmű')})`).join('; '):esc(r[9]||'Nem ellenőrzött')} ${men.length?'Kiírt ár; a szervizdíj alkalmazása külön ellenőrizendő.':''}</p><p><b>Kiszállítás:</b> ${chan.length?chan.map(x=>`${esc(x[2])}: ${x[3]==='Yes'?'a forrásban megtaláltuk':'ebben a körben nem találtuk'} (${esc(x[5])})${x[6]?' '+lk(x[6]):''}`).join(' · '):'Nem vizsgált vagy nincs egyértelmű párosítás.'}</p><details><summary>Étlappéldák és korlátok</summary><p>Megfigyelt kiírt helyszíni árak, eltérő dátumokkal; adag és érvényesség nem feltétlenül egyezik.</p><ul>${examples.map(x=>`<li>${esc(x[5])} — ${fmt(x[7])} · ellenőrizve: ${esc(x[15]||'nem ismert')} · ${lk(x[16])}</li>`).join('')||'<li>Nincs megfelelően besorolt példa.</li>'}</ul><p>${esc(r[7]||'')} ${esc(r[11]||'')}</p></details>${reputation(d,id)}<p class="muted">Helyadat ellenőrzése: ${esc(r[12]||'nem ismert')}. ${lk(r[13],'Helyadat')} · ${lk(r[6],'Étlap')}${r[8]?' · '+lk(r[8],'Menü'):''}</p></article>`}).join('');return `<div class="eyebrow">VERSENYTÁRSAK · MEETINGVÁLOGATÁS</div><h1>Kiket érdemes figyelnünk?</h1><p class="section-intro">Öt hely kiindulásként a közös beszélgetéshez. Zsolt és a séf tudják pontosítani, ki számít igazán versenytársnak.</p><div class="warning">A megfigyelések 2026 októberéből és novemberéből származnak. A „nem találtuk” nem jelenti azt, hogy a szolgáltatás biztosan nem érhető el. A gyalogos távolság becslés.</div><div class="comp-grid">${cards}</div><section class="panel"><h2>Vélemények és értékelések</h2><p>A források platformonként és különböző dátumokból származnak. Alább nyithatók meg a rögzített adatok és témák; az értékeléseket nem átlagoljuk össze.</p></section>`}window.competitorView=view})();
